class CentrePlanning {
 public const TYPES=['Teaching','Review','Admin','Travel','Non-working','Marking','Preparation','Learner support','Staff development'];
 public const SITES=['Doncaster','Sheffield','Remote','Off-site','Between centres'];
 public static function fail(string $message='Planning source or version changed. Reopen and check the current timetable.'):never {throw ValidationException::withMessages(['planning'=>$message]);}
 public static function staff(User $u):bool {return $u->active&&in_array($u->role,[...DirectoryCatalog::STAFF_ROLES,'admin','ceo'],true);}
 public static function legacyRole(User $u):bool {
  if(LearningAccess::manager($u)){return true;}if(!self::staff($u)){return false;}$a=Access::find($u->id);
  try{$h=$a?->history;$v=$h?end($h):null;return $a&&$a->active&&$v&&$v['after']===$a->only(['user_id','granted_by','active','version'])&&$v['role']===$u->role;}catch(\Throwable){return false;}
 }
 public static function hasRole(User $u):bool {return TimetableGovernance::hasRole($u);}
 public static function allowed(User $u):bool {return TimetableGovernance::canEdit($u);}
 public static function actor(User $u,int $auth):User {$u=User::whereKey($u->id)->lockForUpdate()->firstOrFail();\App\Models\TimetableGovernanceState::whereKey(1)->lockForUpdate()->firstOrFail();abort_unless($u->active&&$u->auth_version===$auth&&self::allowed($u),403);return $u;}
 public static function event(User $u,string $event,int $version,array $data=[],?Plan $p=null):void {DB::table('timetable_planning_events')->insert(['actor_id'=>$u->id,'plan_id'=>$p?->id,'event'=>$event,'record_version'=>$version,'payload'=>Crypt::encryptString(json_encode($data,JSON_THROW_ON_ERROR)),'created_at'=>now()]);}
 public static function grant(User $actor,int $auth,User $target,int $version,bool $active):void {DB::transaction(function()use($actor,$auth,$target,$version,$active):void {User::whereIn('id',[$actor->id,$target->id])->orderBy('id')->lockForUpdate()->get();$u=self::actor($actor,$auth);abort_unless(LearningAccess::manager($u),403);$t=User::findOrFail($target->id);TimetableGovernance::legacyChange($u,$t);if(!self::staff($t)||LearningAccess::manager($t)){self::fail('Choose an active staff account; administrator/CEO access already follows its current role.');}$a=Access::whereKey($t->id)->lockForUpdate()->first();if(($a?->version??0)!==$version){self::fail();}$a??=new Access(['user_id'=>$t->id,'version'=>0]);$history=$a->history??[];$a->version++;$a->active=$active;$a->granted_by=$u->id;$history[]=['after'=>$a->only(['user_id','granted_by','active','version']),'role'=>$t->role,'by'=>$u->id,'at'=>now()->toIso8601String()];$a->history=$history;$a->save();self::event($u,'planner_access',$a->version,['user_id'=>$t->id,'active'=>$active]);TimetableGovernance::legacyRecorded($u,$t);},3);}
 public static function roomFields(Room $r):array {return $r->only(['id','site','name','capacity','uses','active','version']);}
 public static function roomIntact(Room $r):bool {try{$h=$r->history??[];$last=$h?end($h):null;return $last&&$last['after']===self::roomFields($r);}catch(\Throwable){return false;}}
 public static function room(User $actor,int $auth,Room $record,int $version,array $d):void {DB::transaction(function()use($actor,$auth,$record,$version,$d):void {$u=self::actor($actor,$auth);$r=Room::whereKey($record->id)->lockForUpdate()->firstOrFail();if($r->version!==$version||!is_int($d['capacity'])||$d['capacity']<1||$d['capacity']>200||array_diff($d['uses'],['Teaching','Review','Admin'])){self::fail('Set a checked capacity1–200 and suitable room uses.');}$before=self::roomFields($r);$r->capacity=$d['capacity'];$r->uses=array_values(array_unique($d['uses']));$r->active=(bool)$d['active'];$r->version++;$h=$r->history??[];$h[]=['before'=>$before,'after'=>self::roomFields($r),'by'=>$u->id,'at'=>now()->toIso8601String()];$r->history=$h;$r->save();self::event($u,'room_checked',$r->version,['room_id'=>$r->id,'before'=>$before,'after'=>self::roomFields($r)]);},3);}
 public static function minutes(string $time):int {if(!preg_match('/^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/D',$time)){self::fail('Use a valid24-hour time.');}return (int)substr($time,0,2)*60+(int)substr($time,3,2);}
 public static function clock(int $minutes):string {return sprintf('%02d:%02d',intdiv($minutes,60),$minutes%60);}
 public static function dates(string $first,int $weeks,bool $future=true):array {if($weeks<1||$weeks>26){self::fail('Choose1–26 weekly occurrences.');}try{$d=Carbon::createFromFormat('!Y-m-d',$first,config('app.timezone'));}catch(\Throwable){self::fail('Use a valid start date.');}if($d->toDateString()!==$first||($future&&$d->lt(today()))||$d->copy()->addWeeks($weeks-1)->gt(today()->addYear())){self::fail('Use current/future dates, within one year.');}return array_map(fn($n)=>$d->copy()->addWeeks($n)->toDateString(),range(0,$weeks-1));}
 public static function windowProof(Window $w):array {return ['user_id'=>$w->user_id,'date'=>$w->work_date->toDateString(),'working'=>$w->working,'start'=>$w->start_time,'end'=>$w->end_time,'version'=>$w->version,'by'=>$w->updated_by];}
 public static function windowIntact(Window $w):bool {try{return $w->proof===self::windowProof($w);}catch(\Throwable){return false;}}
 public static function windowSource(User $staff,array $dates,bool $lock=false):array {$u=User::findOrFail($staff->id);$rows=Window::where('user_id',$u->id)->whereIn(DB::raw('DATE(work_date)'),$dates)->orderBy('work_date')->when($lock,fn($q)=>$q->lockForUpdate())->get();return ['staff'=>ReviewAppointments::seal($u),'dates'=>$dates,'rows'=>$rows->map(fn($w)=>['fields'=>self::windowProof($w),'valid'=>self::windowIntact($w)])->all()];}
 public static function windows(User $actor,int $auth,User $staff,array $dates,string $expected,bool $working,?string $start,?string $end):void {DB::transaction(function()use($actor,$auth,$staff,$dates,$expected,$working,$start,$end):void {User::whereIn('id',[$actor->id,$staff->id])->orderBy('id')->lockForUpdate()->get();$u=self::actor($actor,$auth);$t=User::findOrFail($staff->id);if(!self::staff($t)||!$dates||count($dates)>26||count(array_unique($dates))!==count($dates)||ReviewedImports::hash(self::windowSource($t,$dates,true))!==$expected){self::fail('Working dates/staff changed; reload the exact preview.');}if($working&&(!$start||!$end||self::minutes($end)-self::minutes($start)<5||self::minutes($end)-self::minutes($start)>720)){self::fail('Use a same-day working window5–720 minutes.');}foreach($dates as$date){self::dates($date,1);$w=Window::where('user_id',$t->id)->whereDate('work_date',$date)->first()??new Window(['user_id'=>$t->id,'work_date'=>$date,'version'=>0]);$before=$w->exists?self::windowProof($w):null;$w->working=$working;$w->start_time=$working?$start:null;$w->end_time=$working?$end:null;$w->version++;$w->updated_by=$u->id;$w->proof=self::windowProof($w);$w->save();self::event($u,'working_time',$w->version,['before'=>$before,'after'=>self::windowProof($w)]);}},3);}
 private static function capture(array $d,bool $lock=false,bool $future=true):array {
  $dates=self::dates($d['date'],(int)$d['weeks'],$future);$from=self::minutes($d['start']);$to=self::minutes($d['end']);if($to-$from<5||$to-$from>720||!in_array($d['kind'],self::TYPES,true)||!in_array($d['site'],self::SITES,true)||trim($d['title'])===''||mb_strlen($d['title'])>160||preg_match('/[\x00-\x1F\x7F]/u',$d['title'])){self::fail('Use a safe short title and same-day5–720 minute activity.');}
  $u=User::whereKey((int)$d['staff_id'])->when($lock,fn($q)=>$q->lockForUpdate())->firstOrFail();if(!self::staff($u)){self::fail('Choose current active GTA staff.');}$room=($d['room_id']??null)?Room::whereKey((int)$d['room_id'])->when($lock,fn($q)=>$q->lockForUpdate())->firstOrFail():null;$group=($d['group_id']??null)?TutorGroup::whereKey((int)$d['group_id'])->when($lock,fn($q)=>$q->lockForUpdate())->firstOrFail():null;
  if($room&&$room->site!==$d['site']||$d['kind']==='Travel'&&($d['site']!=='Between centres'||$room||$group)||$d['kind']!=='Travel'&&$d['site']==='Between centres'||$d['kind']!=='Teaching'&&$group){self::fail('Match room/site and use a separate Travel activity between centres. Only Teaching uses a group.');}
  if($d['kind']==='Teaching'&&(!$group||!$group->active||$group->tutor_id!==$u->id||$u->role!=='tutor'||!$room||!isset($d['headcount'])||(int)$d['headcount']<1||(int)$d['headcount']>200)){self::fail('Teaching needs an active group assigned to this primary Tutor, a room and checked expected headcount1–200.');}
  $members=$group?Apprentice::where('tutor_group_id',$group->id)->orderBy('id')->pluck('id')->all():[];$args=['staff_id'=>$u->id,'date'=>$d['date'],'weeks'=>(int)$d['weeks'],'start'=>$d['start'],'end'=>$d['end'],'kind'=>$d['kind'],'site'=>$d['site'],'room_id'=>$room?->id,'group_id'=>$group?->id,'title'=>trim($d['title']),'headcount'=>$group?(int)$d['headcount']:null];$rows=[];foreach($dates as$date){$time=Carbon::parse($date.' '.$d['start'],config('app.timezone'));if(($future&&!$time->gt(now()))||$time->format('H:i')!==$d['start']){self::fail('Every activity must start in the future at a valid local time.');}$rows[]=['work_date'=>$date,'start_time'=>$d['start'],'end_time'=>$d['end'],'staff_id'=>$u->id,'room_id'=>$room?->id,'group_id'=>$group?->id,'kind'=>$d['kind'],'site'=>$d['site'],'title'=>trim($d['title']),'headcount'=>$args['headcount'],'members'=>$members];}
  return ['args'=>$args,'rows'=>$rows,'staff'=>['id'=>$u->id,'name'=>$u->name,'seal'=>ReviewAppointments::seal($u)],'room'=>$room?['fields'=>self::roomFields($room),'valid'=>self::roomIntact($room)]:null,'group'=>$group?['name'=>$group->name,'hash'=>ReviewedImports::hash($group->getAttributes()),'members'=>$members]:null,'windows'=>self::windowSource($u,$dates,$lock),'timezone'=>config('app.timezone'),'cross_site_minutes'=>config('timetable_planning.cross_site_minutes')];
 }
 public static function intact(Plan $p):bool {try{$s=$p->source;if(!$s||ReviewedImports::hash($s)!==$p->source_hash||$s['created_by']!==$p->created_by||$s['request']!==$p->request_token){return false;}$rows=Entry::where('plan_id',$p->id)->orderBy('work_date')->get();return $rows->count()===count($s['data']['rows'])&&$rows->values()->every(function($e,$i)use($s){$want=$s['data']['rows'][$i];return $e->source_hash===ReviewedImports::hash($want)&&$e->work_date->toDateString()===$want['work_date']&&$e->only(['start_time','end_time','staff_id','room_id','group_id','kind','site','title','headcount'])===collect($want)->except('work_date','members')->all();});}catch(\Throwable){return false;}}
 public static function fresh(Plan $p,bool $lock=false):bool {try{return self::intact($p)&&ReviewedImports::hash(self::capture($p->source['data']['args'],$lock,false))===ReviewedImports::hash($p->source['data']);}catch(\Throwable){return false;}}
 public static function save(User $actor,int $auth,?Plan $record,int $version,string $token,array $d):Plan {if(!Str::isUuid($token)){self::fail('Reload a fresh form.');}return DB::transaction(function()use($actor,$auth,$record,$version,$token,$d):Plan {User::whereIn('id',[$actor->id,(int)$d['staff_id']])->orderBy('id')->lockForUpdate()->get();$u=self::actor($actor,$auth);$data=self::capture($d,true);$p=$record?Plan::whereKey($record->id)->lockForUpdate()->firstOrFail():null;if($p){TimetableGovernance::guardPlan($u,$p);}if(!$p&&($old=Plan::where('request_token',$token)->lockForUpdate()->first())){if(self::intact($old)&&$old->created_by===$u->id&&$old->source['data']===$data){return $old;}self::fail('Request token already used for different source.');}if($p&&($p->state!=='Draft'||$p->version!==$version||!self::intact($p))||!$p&&$version!==0){self::fail();}$before=$p?['source'=>$p->source,'check'=>$p->check_proof]:null;$p??=new Plan(['created_by'=>$u->id,'request_token'=>$token,'version'=>0]);$p->id??=(string)Str::uuid();$p->version++;$p->state='Draft';$p->source=['created_by'=>$p->created_by,'request'=>$p->request_token,'source_version'=>$p->version,'prepared_by'=>$u->id,'data'=>$data];$p->source_hash=ReviewedImports::hash($p->source);$p->check_proof=null;$p->save();Entry::where('plan_id',$p->id)->delete();foreach($data['rows']as$row){Entry::create(['plan_id'=>$p->id,...collect($row)->except('members')->all(),'source_hash'=>ReviewedImports::hash($row)]);}self::event($u,'draft_saved',$p->version,['before'=>$before,'source_hash'=>$p->source_hash],$p);return $p;},3);}
 public static function published(Plan $p):bool {try{$v=$p->publication;return self::intact($p)&&$v&&$p->check_proof&&$v['source_hash']===$p->source_hash&&$v['check_hash']===ReviewedImports::hash($p->check_proof)&&$v['version']===$p->check_proof['version']+1&&$v['at']===$p->published_at?->toIso8601String()&&($p->state==='Published'&&$p->version===$v['version']||self::withdrawn($p));}catch(\Throwable){return false;}}
 public static function withdrawn(Plan $p):bool {try{$v=$p->withdrawal;return self::intact($p)&&$p->state==='Withdrawn'&&$v&&$v['source_hash']===$p->source_hash&&$v['version']===$p->version&&$v['publication_hash']===ReviewedImports::hash($p->publication);}catch(\Throwable){return false;}}
 public static function liveRows(Plan $p):array {if(!self::published($p)){return [];}$rows=$p->source['data']['rows'];if($p->state==='Withdrawn'){$rows=array_values(array_filter($rows,fn($r)=>Carbon::parse($r['work_date'].' '.$r['start_time'],$p->source['data']['timezone'])->lte(Carbon::parse($p->withdrawal['at']))));}$stale=!self::fresh($p);return array_map(fn($r)=>$r+['key'=>'p'.$p->id.':'.$r['work_date'],'plan_id'=>$p->id,'external'=>false,'stale'=>$stale],$rows);}
 public static function busy(array $dates,?string $ignore=null,bool $lock=false):array {
  $out=[];$uncertain=[];$linked=[];$plans=Plan::whereIn('id',Entry::whereIn(DB::raw('DATE(work_date)'),$dates)->select('plan_id'))->where('id','!=',$ignore??'')->whereIn('state',['Published','Withdrawn'])->orderBy('id')->when($lock,fn($q)=>$q->lockForUpdate())->get();foreach($plans as$p){if(!self::intact($p)||!self::published($p)){if(in_array($p->state,['Published','Withdrawn'],true)){$uncertain[]='Published planning evidence needs repair: '.$p->id;}continue;}foreach(self::liveRows($p)as$row){if(in_array($row['work_date'],$dates,true)){$entry=Entry::where('plan_id',$p->id)->whereDate('work_date',$row['work_date'])->first();if($entry&&self::linkCurrent($entry,$p)){$linked[]=$entry->training_session_id;$row['linked_session']=$entry->training_session_id;}$out[]=$row;}}}
  foreach(TrainingSession::with('group')->whereIn(DB::raw('DATE(session_date)'),$dates)->where('state','!=','Cancelled')->whereNotIn('id',$linked)->orderBy('id')->when($lock,fn($q)=>$q->lockForUpdate())->get()as$s){$roster=RegisterFollowup::roster($s);if(!$s->group?->tutor_id||!TimetableChanges::time($s->start_time)||!TimetableChanges::time($s->end_time)||$s->end_time<=$s->start_time||!$roster['shape']||$roster['duplicates']){$uncertain[]='Existing register session needs source check: '.$s->id;continue;}$out[]=['key'=>'s'.$s->id,'plan_id'=>null,'work_date'=>$s->session_date->toDateString(),'start_time'=>$s->start_time,'end_time'=>$s->end_time,'staff_id'=>$s->group->tutor_id,'room_id'=>null,'group_id'=>$s->tutor_group_id,'kind'=>'Teaching','site'=>'Unknown','title'=>'Existing register session','headcount'=>count($roster['ids']),'members'=>$roster['ids'],'external'=>true,'stale'=>false,'seal'=>ReviewedImports::hash($s->getAttributes())];}
  foreach(ReviewAppointment::whereDate('starts_at','>=',min($dates))->whereDate('starts_at','<=',max($dates))->where('state','Published')->orderBy('id')->when($lock,fn($q)=>$q->lockForUpdate())->get()as$p){if(!ReviewAppointments::intact($p)){$uncertain[]='Existing review appointment needs source check: '.$p->id;continue;}$l=$p->source['logistics'];if(!in_array($l['date'],$dates,true)){continue;}$out[]=['key'=>'r'.$p->id,'plan_id'=>null,'work_date'=>$l['date'],'start_time'=>$l['start'],'end_time'=>$l['end'],'staff_id'=>$p->source['basis']['host_id'],'room_id'=>null,'group_id'=>null,'kind'=>'Review','site'=>'Unknown','title'=>'Existing review appointment','headcount'=>null,'members'=>[$p->apprentice_id],'external'=>true,'stale'=>!ReviewAppointments::current($p),'seal'=>ReviewedImports::hash($p->getAttributes())];}
  usort($out,fn($a,$b)=>[$a['work_date'],$a['start_time'],$a['key']]<=>[$b['work_date'],$b['start_time'],$b['key']]);return TimetableCover::overlay(['rows'=>$out,'uncertain'=>$uncertain],$dates);
 }
 public static function overlap(array $a,array $b):bool {return $a['work_date']===$b['work_date']&&$a['start_time']<$b['end_time']&&$a['end_time']>$b['start_time'];}
 public static function shared(array $a,array $b):bool {return $a['staff_id']===$b['staff_id']||$a['room_id']&&$a['room_id']===$b['room_id']||$a['group_id']&&$a['group_id']===$b['group_id']||(bool)array_intersect($a['members'],$b['members']);}
 public static function projection(array $args,bool $lock=false):array {return self::capture($args,$lock);}
 // Same canonical checks for a captured candidate and an explicitly supplied busy snapshot.
 // This is read-only; only save/check/publish can create a reservation.
 public static function inspectProjection(array $data,array $busy):array {
  $errors=$busy['uncertain'];$warnings=[];
  foreach($data['rows']as$row){if(!Carbon::parse($row['work_date'].' '.$row['start_time'],$data['timezone'])->gt(now())){$errors[]='An occurrence has started; prepare a new future draft.';}$w=collect($data['windows']['rows'])->first(fn($v)=>$v['fields']['date']===$row['work_date']);if(!$w||!$w['valid']||!$w['fields']['working']||$row['start_time']<$w['fields']['start']||$row['end_time']>$w['fields']['end']){$errors[]=$row['work_date'].': verified working time is missing or does not cover the activity.';}$room=$data['room'];if($row['room_id']&&(!$room['valid']||!$room['fields']['active']||!in_array(in_array($row['kind'],TimetableDuties::OTHER_TYPES,true)?'Admin':$row['kind'],$room['fields']['uses']??[],true))){$errors[]='Check active room capacity/suitable use before publication.';}if($row['kind']==='Teaching'&&(($room['fields']['capacity']??0)<$row['headcount']||count($row['members'])>$row['headcount'])){$errors[]='Expected/group headcount exceeds checked room capacity or expected headcount understates current group membership.';}if(!$row['room_id']&&in_array($row['site'],['Doncaster','Sheffield'],true)&&!in_array($row['kind'],['Non-working','Travel'],true)){$warnings[]='On-site non-teaching activity has no room allocation.';}foreach($busy['rows']as$other){if(self::shared($row,$other)&&self::overlap($row,$other)){$errors[]=$row['work_date'].': staff, room, group or learner clash with '.($other['key']??'proposed activity');}if($other['staff_id']===$row['staff_id']&&$other['site']==='Unknown'){$warnings[]=$row['work_date'].': existing session/appointment room or site is unknown; check travel/location separately.';}}}
  // A cross-centre gap needs both an agreed minimum and an explicit busy Travel activity.
  $all=[...$busy['rows'],...$data['rows']];$days=[];foreach($all as$row){if($row['staff_id']!==$data['args']['staff_id']){continue;}$days[$row['staff_id'].':'.$row['work_date']][]=$row;}foreach($days as$day){usort($day,fn($a,$b)=>$a['start_time']<=>$b['start_time']);$physical=array_values(array_filter($day,fn($r)=>in_array($r['site'],['Doncaster','Sheffield'],true)&&$r['kind']!=='Non-working'));for($i=1;$i<count($physical);$i++){$a=$physical[$i-1];$b=$physical[$i];if($a['site']===$b['site']){continue;}$need=config('timetable_planning.cross_site_minutes');$intervals=[];foreach($day as$t){if($t['kind']==='Travel'&&$t['start_time']>=$a['end_time']&&$t['end_time']<=$b['start_time']){$intervals[]=[self::minutes($t['start_time']),self::minutes($t['end_time'])];}}if(!is_numeric($need)||(int)$need<5||(int)$need>180||CentreTimetable::unionMinutes($intervals)<(int)$need){$errors[]='Cross-site day needs a GTA-confirmed travel minimum and a covering explicit Travel activity.';}}}
  return ['errors'=>array_values(array_unique($errors)),'warnings'=>array_values(array_unique($warnings)),'fingerprint'=>ReviewedImports::hash($busy)];
 }
 public static function inspect(Plan $p,bool $lock=false):array {
  if(!self::intact($p)){return ['errors'=>['Draft evidence needs repair'],'warnings'=>[],'fingerprint'=>null];}
  $data=$p->source['data'];$busy=self::busy(array_column($data['rows'],'work_date'),$p->id,$lock);$r=self::inspectProjection($data,$busy);
  if(!self::fresh($p,$lock)){$r['errors'][]='Staff, room, group, working time, dates or configuration changed; update the draft.';}
  return $r;
 }
 public static function check(User $actor,int $auth,Plan $record,int $version,bool $warningsAccepted):void {DB::transaction(function()use($actor,$auth,$record,$version,$warningsAccepted):void {$u=self::actor($actor,$auth);$p=Plan::whereKey($record->id)->lockForUpdate()->firstOrFail();TimetableGovernance::guardPlan($u,$p);if($p->state!=='Draft'||$p->version!==$version){self::fail();}$r=self::inspect($p,true);if($r['errors']||$r['warnings']&&!$warningsAccepted){self::fail(implode(' ',[...$r['errors'],...$r['warnings']]));}$p->version++;$p->check_proof=['version'=>$p->version,'source_hash'=>$p->source_hash,'fingerprint'=>$r['fingerprint'],'warnings'=>$r['warnings'],'by'=>$u->id,'auth'=>$u->auth_version,'at'=>now()->toIso8601String()];$p->save();self::event($u,'draft_checked',$p->version,['source_hash'=>$p->source_hash,'warnings'=>$r['warnings']],$p);},3);}
 public static function publish(User $actor,int $auth,Plan $record,int $version):void {DB::transaction(function()use($actor,$auth,$record,$version):void {$ids=[$actor->id,$record->source['data']['args']['staff_id']];User::whereIn('id',$ids)->orderBy('id')->lockForUpdate()->get();$u=self::actor($actor,$auth);$p=Plan::whereKey($record->id)->lockForUpdate()->firstOrFail();TimetableGovernance::guardPlan($u,$p);if(!self::intact($p)||$p->state!=='Draft'||$p->version!==$version||!$p->check_proof||$p->check_proof['version']!==$p->version||$p->check_proof['source_hash']!==$p->source_hash){self::fail('Check this exact current draft before publishing.');}$checker=User::find($p->check_proof['by']);if(!$checker||!self::allowed($checker)||$checker->auth_version!==$p->check_proof['auth']){self::fail('Checker access changed; check again.');}$r=self::inspect($p,true);if($r['errors']||$r['fingerprint']!==$p->check_proof['fingerprint']||$r['warnings']!==$p->check_proof['warnings']){self::fail('Timetable or source changed after checking. Check the current draft again.');}$p->version++;$p->state='Published';$p->published_at=now()->setMicrosecond(0);$p->publication=['source_hash'=>$p->source_hash,'check_hash'=>ReviewedImports::hash($p->check_proof),'version'=>$p->version,'by'=>$u->id,'at'=>$p->published_at->toIso8601String()];$p->save();self::event($u,'plan_published',$p->version,['rows'=>count($p->source['data']['rows']),'no_register_created'=>true],$p);},3);}
 public static function withdraw(User $actor,int $auth,Plan $record,int $version,string $reason):void {DB::transaction(function()use($actor,$auth,$record,$version,$reason):void {$u=self::actor($actor,$auth);$p=Plan::whereKey($record->id)->lockForUpdate()->firstOrFail();TimetableGovernance::guardPlan($u,$p);if(!self::intact($p)||$p->version!==$version||!in_array($p->state,['Draft','Published'],true)||!filled($reason)){self::fail();}$future=array_filter($p->source['data']['rows'],fn($r)=>Carbon::parse($r['work_date'].' '.$r['start_time'],$p->source['data']['timezone'])->gt(now()));if(!$future){self::fail('No future occurrences remain to withdraw.');}$p->version++;$p->state='Withdrawn';$p->withdrawal=['source_hash'=>$p->source_hash,'publication_hash'=>ReviewedImports::hash($p->publication),'version'=>$p->version,'by'=>$u->id,'at'=>now()->toIso8601String(),'reason'=>$reason];$p->save();self::event($u,'future_withdrawn',$p->version,['future_occurrences'=>count($future),'reason'=>$reason],$p);},3);}
 public static function matchesRegister(Entry $entry,TrainingSession $s):bool {
  try{$p=Plan::findOrFail($entry->plan_id);$row=collect($p->source['data']['rows'])->firstWhere('work_date',$entry->work_date->toDateString());$roster=RegisterFollowup::roster($s);$a=$roster['ids'];$b=$row['members']??[];sort($a);sort($b);return $row&&$entry->kind==='Teaching'&&$s->state==='Planned'&&$s->tutor_group_id===$entry->group_id&&$s->group?->tutor_id===$entry->staff_id&&$s->session_date->toDateString()===$entry->work_date->toDateString()&&$s->start_time===$entry->start_time&&$s->end_time===$entry->end_time&&$roster['shape']&&$a===$b;}catch(\Throwable){return false;}
 }
 public static function linkCurrent(Entry $entry,Plan $p):bool {
  try{$v=$entry->link_proof;if(($v['mode']??null)==='delivery'){return OccurrenceRegisters::current($entry,$p);}$s=$entry->training_session_id?TrainingSession::find($entry->training_session_id):null;return self::intact($p)&&$v&&$s&&$v['plan_id']===$p->id&&$v['source_hash']===$p->source_hash&&$v['entry_id']===$entry->id&&$v['session_id']===$s->id&&$v['session_hash']===ReviewedImports::hash($s->getAttributes())&&self::matchesRegister($entry,$s);}catch(\Throwable){return false;}
 }
 public static function link(User $actor,int $auth,Entry $record,int $planVersion,TrainingSession $session,int $sessionVersion):void {
  DB::transaction(function()use($actor,$auth,$record,$planVersion,$session,$sessionVersion):void {User::whereIn('id',[$actor->id,$record->staff_id])->orderBy('id')->lockForUpdate()->get();$u=self::actor($actor,$auth);$p=Plan::whereKey($record->plan_id)->lockForUpdate()->firstOrFail();TimetableGovernance::guardPlan($u,$p);$e=Entry::whereKey($record->id)->lockForUpdate()->firstOrFail();$s=TrainingSession::whereKey($session->id)->lockForUpdate()->firstOrFail();if($p->version!==$planVersion||$p->state!=='Published'||!self::published($p)||!self::fresh($p,true)||$s->version!==$sessionVersion||!TimetableChanges::starts($s)->gt(now())||$s->marks()->exists()||filled($s->delivered_learning)||!self::matchesRegister($e,$s)){self::fail('Link the exact current future unmarked register with matching staff/group/date/time/roster. No register data is edited.');}$other=Entry::where('training_session_id',$s->id)->where('id','!=',$e->id)->lockForUpdate()->first();if($other){self::fail('Register already has a planning link. Reconcile it explicitly before linking another.');}$before=$e->link_proof;$e->training_session_id=$s->id;$e->link_proof=['plan_id'=>$p->id,'source_hash'=>$p->source_hash,'entry_id'=>$e->id,'session_id'=>$s->id,'session_hash'=>ReviewedImports::hash($s->getAttributes()),'by'=>$u->id,'at'=>now()->toIso8601String()];$e->save();self::event($u,'register_linked',$p->version,['before'=>$before,'proof'=>$e->link_proof],$p);},3);
 }
 public static function unlink(User $actor,int $auth,Entry $record,int $version,string $expected):void {
  DB::transaction(function()use($actor,$auth,$record,$version,$expected):void {$u=self::actor($actor,$auth);$p=Plan::whereKey($record->plan_id)->lockForUpdate()->firstOrFail();TimetableGovernance::guardPlan($u,$p);$e=Entry::whereKey($record->id)->lockForUpdate()->firstOrFail();if(!self::intact($p)||$p->version!==$version||!$e->link_proof||ReviewedImports::hash($e->link_proof)!==$expected){self::fail('Register link changed; reload before unlinking.');}$before=$e->link_proof;$e->training_session_id=null;$e->link_proof=null;$e->save();self::event($u,'register_unlinked',$p->version,['before'=>$before,'actual_register_unchanged'=>true],$p);},3);
 }

}
